from pathlib import Path
import json,os
E=Path('experiments/main-orc-combat-recovery-v8/rear');spec=json.loads((E/'temporal-spec.json').read_text());manifest=json.loads((E/'candidate4manifest.json').read_text());data={}
def rel(p):return os.path.relpath(p,E).replace('\\','/')
def compact(c):return{'clipRevision':c['revision'],'frames':[{'png':rel(f['png']),'body':rel(f['layers']['body']['png']),'phase':f['phase'],'durationMs':f['durationMs']}for f in c['frames']]}
for k,s in spec.items():
 clips={d:compact(json.loads(Path(v['clip']).read_text()))for d,v in s['frontals'].items()}
 for cell in manifest['cells']:
  if cell['action']==k:clips[cell['direction']]=compact(json.loads(Path(cell['clip']).read_text()))
 assert all(len(c['frames'])==s['frameCount']and[f['durationMs']for f in c['frames']]==s['durationsMs']and[f['phase']for f in c['frames']]==[f['phase']for f in s['phases']]for c in clips.values())
 data[k]={'spec':s,'clips':clips}
(E/'preview-data.json').write_text(json.dumps(data,indent=2))
html='''<!doctype html><meta charset="utf-8"><title>Orc V1 V8 — traseiras alinhadas</title><style>body{margin:24px;background:#1a1e25;color:#dfe6f0;font:16px system-ui}a{color:#98ceff}header{position:sticky;top:0;background:#1a1e25;z-index:5;padding:8px;border-bottom:1px solid #4b5a6c}button,select,input{margin:5px;padding:7px}section.views{display:flex;flex-wrap:nowrap;gap:16px;overflow-x:auto;margin-top:24px;align-items:flex-start}article{background:#283140;padding:12px;flex:0 0 auto}h3{font-size:17px;margin:0 0 10px}canvas,img{image-rendering:pixelated;background:repeating-conic-gradient(#354052 0% 25%,#2d3645 0% 50%) 50%/16px 16px}canvas{width:256px;height:256px;outline:2px solid transparent}.impact{outline:2px solid #ffb54e}p{max-width:1200px}.meta{font-size:13px;color:#bfccdd;max-width:300px}table{border-collapse:collapse;margin:18px 0;font-size:14px}td,th{padding:8px;border:1px solid #4f6077}tbody tr{cursor:pointer}tbody tr.active{background:#3a4d65}tbody tr.hit{color:#ffd18a}progress{width:280px}#trio{width:100%;max-width:1536px}details{margin:20px 0}.small{font-size:14px;color:#bccadc}</style><h1>Orc V1 · V8 · grade frontal comum</h1><p>V8_REAR_ALIGNED · TECHNICALLY_COMPLETE · VISUAL_REVIEW_REQUIRED · PENDING_CREATOR</p><p>Sword: 13 quadros / 730 ms. Axe: 12 quadros / 1005 ms. As quatro direções usam o mesmo relógio. Impacto é o início da fase contact (Sword 325 ms) / heavy-impact (Axe 410 ms), calculado pelas durações. Referências frontais V7 protegidas, sem alterações.</p><p><a href="report.md">Relatório</a> · <a href="phase-comparison.md">Tabela comparativa</a> · <a href="phase-comparison.csv">CSV</a> · <a href="phase-comparison.json">JSON</a> · <a href="verification.json">Verificações</a></p><header><select id="kind"><option>Sword</option><option>Axe</option></select><button id="play">Pausar</button><button id="prev">◀ Quadro</button><button id="next">Quadro ▶</button><select id="speed"><option value="1">1× normal</option><option value="0.5">0,5× lenta</option></select><select id="zoom"><option value="1">1× · corpo128</option><option value="0.5">Tático · corpo64</option><option value="2">Zoom 2×</option><option value="3">Zoom 3×</option></select><label><input id="body" type="checkbox">body-only</label><label><input id="repeat" type="checkbox" checked>repetir revisão</label><button id="impact">Ir ao impacto</button><br><input id="frame" type="range" min="0" max="12" value="0"><progress id="progress" value="0" max="730"></progress><span id="state"></span></header><section class="views" id="views"></section><p class="small">Passo a quadro e clique na tabela pausam a reprodução. Os clipes são ações únicas; “repetir revisão” serve só à inspeção. O corpo mantém canvas nativo 128; o composto 256 acomoda o item independente.</p><h2>Fases e relógio — quatro direções</h2><div id="table"></div><h2>back_l: ápice V7 → descida manual V8 → contato V7</h2><p>Trio inspecionado antes da montagem completa. A pose de ápice Sword mantém os pixels V7 validados; apenas a ligação descendente foi reautorada localmente.</p><a id="trioLink"><img id="trio"></a><details><summary>Nota sobre metadados legados dos frontais</summary><p>Alguns contactEvent antigos não coincidem com o relógio da fase rotulada. Esses arquivos protegidos permanecem intactos. Esta comparação usa posição do quadro + fase + durações acumuladas; os novos clipes traseiros registram o início correto da fase. Divergências detalhadas no relatório.</p></details><script>const data=DATA;let kind='Sword',playing=true,elapsed=0,last=0,rate=1,zoom=1,body=false;const cache={},views=[];for(const p of Object.values(data))for(const c of Object.values(p.clips))for(const f of c.frames)for(const k of ['png','body'])if(!cache[f[k]]){const im=new Image();im.dataset.url=f[k];cache[f[k]]=im}for(const [dir,title]of[['front_r','front_r · protegido'],['front_l','front_l · protegido'],['back_r','back_r · V8 candidato'],['back_l','back_l · V8 candidato']]){const a=document.createElement('article');a.innerHTML='<h3>'+title+'</h3>';const c=document.createElement('canvas');c.width=c.height=256;c.dataset.direction=dir;a.append(c);const label=document.createElement('p');label.className='meta';a.append(label);document.querySelector('#views').append(a);views.push({dir,c,label})}window.ready=(async()=>{const all=Object.values(cache);for(let i=0;i<all.length;i+=6)await Promise.all(all.slice(i,i+6).map(im=>{im.src=im.dataset.url;return im.decode()}))})().then(()=>{window.loaded=true;updateInfo();draw()});function clock(){const s=data[kind].spec;return document.querySelector('#repeat').checked?elapsed%s.durationMs:Math.min(elapsed,s.durationMs-.001)}function index(){const t=clock();return data[kind].spec.phases.findIndex(f=>t>=f.startMs&&t<f.endMs)}function draw(){if(!window.loaded)return;const p=data[kind],s=p.spec,i=index(),phase=s.phases[i];for(const v of views){const f=p.clips[v.dir].frames[i],url=f[body?'body':'png'],ctx=v.c.getContext('2d');ctx.clearRect(0,0,256,256);ctx.imageSmoothingEnabled=false;ctx.drawImage(cache[url],0,0);v.c.style.width=v.c.style.height=256*zoom+'px';v.c.classList.toggle('impact',i===s.impactFrame);v.c.dataset.frame=i;v.c.dataset.phase=f.phase;v.c.dataset.source=url;v.label.textContent='F'+String(i).padStart(2,'0')+' · '+f.phase+' · '+phase.startMs+'–'+phase.endMs+' ms'}document.querySelector('#frame').value=i;document.querySelector('#progress').value=clock();document.querySelector('#state').textContent=' F'+String(i).padStart(2,'0')+' · '+phase.phase+' · '+Math.floor(clock())+' / '+s.durationMs+' ms'+(i===s.impactFrame?' · IMPACTO':'');for(const row of document.querySelectorAll('tbody tr'))row.classList.toggle('active',+row.dataset.index===i)}function setFrame(i){const s=data[kind].spec;i=(i+s.frameCount)%s.frameCount;elapsed=s.phases[i].startMs;playing=false;document.querySelector('#play').textContent='Reproduzir';draw()}function setTime(ms){elapsed=ms;playing=false;document.querySelector('#play').textContent='Reproduzir';draw()}function updateInfo(){const s=data[kind].spec;document.querySelector('#frame').max=s.frameCount-1;document.querySelector('#progress').max=s.durationMs;document.querySelector('#table').innerHTML='<table><thead><tr><th>F</th><th>Fase</th><th>ms</th><th>front_r início</th><th>front_l início</th><th>back_r início</th><th>back_l início</th></tr></thead><tbody>'+s.phases.map(f=>'<tr data-index="'+f.index+'" class="'+(f.index===s.impactFrame?'hit':'')+'"><td>'+String(f.index).padStart(2,'0')+'</td><td>'+f.phase+'</td><td>'+f.durationMs+'</td>'+Array(4).fill('<td>'+f.startMs+' ms</td>').join('')+'</tr>').join('')+'</tbody></table>';for(const r of document.querySelectorAll('tbody tr'))r.onclick=()=>setFrame(+r.dataset.index);const path='transitions/'+kind.toLowerCase()+'/apex-descent-impact.png';document.querySelector('#trio').src=path;document.querySelector('#trioLink').href=path}document.querySelector('#kind').onchange=e=>{kind=e.target.value;elapsed=0;updateInfo();draw()};document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pausar':'Reproduzir';if(playing&&elapsed>=data[kind].spec.durationMs-.01)elapsed=0};document.querySelector('#prev').onclick=()=>setFrame(index()-1);document.querySelector('#next').onclick=()=>setFrame(index()+1);document.querySelector('#frame').oninput=e=>setFrame(+e.target.value);document.querySelector('#speed').onchange=e=>rate=+e.target.value;document.querySelector('#zoom').onchange=e=>{zoom=+e.target.value;draw()};document.querySelector('#body').onchange=e=>{body=e.target.checked;draw()};document.querySelector('#repeat').onchange=draw;document.querySelector('#impact').onclick=()=>setFrame(data[kind].spec.impactFrame);function tick(t){const dt=last?Math.min(t-last,100):0;last=t;if(playing&&window.loaded){elapsed+=dt*rate;if(!document.querySelector('#repeat').checked&&elapsed>=data[kind].spec.durationMs){elapsed=data[kind].spec.durationMs-.001;playing=false;document.querySelector('#play').textContent='Reproduzir'}draw()}requestAnimationFrame(tick)}requestAnimationFrame(tick);</script>'''
(E/'preview.html').write_text(html.replace('DATA',json.dumps(data)),encoding='utf-8');print('Four-direction shared-clock preview written')
